\frac{C(s)}{-R(s)} &amp; =\frac{G(s)}{1-G(s)-G(s)}=\frac{G(s)}{1-2 G(s)} \\
\frac{C(s)}{R(s)} &amp; =\frac{-G(s)}{1-2 G(s)}
\end{aligned}\]

\[\begin{aligned}
t_{\mathrm{cm}} &amp; =\frac{C}{I_{0}} V_{s} \\
&amp; =\frac{10 \cdot 10^{-6}}{10} \cdot 50 \\
&amp; =50 \mu \mathrm{s}
